"""Plain-language, evidence-linked experiment design embedded in the TODO."""
from html import escape as e
def render(d,table):
 h='<section class="thinking-design" id="thinking-design"><h3>The two questions we want the experiments to answer</h3><div class="thinking-grid">'+''.join('<article class="catalog-question"><h4>'+e(x['question'])+'</h4><p>'+e(x['meaning'])+'</p></article>' for x in d['main_questions'])+'</div><p>'+e(d['input_vs_work'])+'</p><p><strong>Recommendation:</strong> '+e(d['recommendation'])+'</p>'
 h+='<p>There is close prior work. <a href="https://arxiv.org/abs/2601.19952">LTS-VoiceAgent (Zou et al., 2026)</a> already combines semantic thought triggers and maintained state. <a href="https://arxiv.org/abs/2607.03093">Proactive Thinking (Wang et al., 2026)</a> prepares for predicted user replies. <a href="https://arxiv.org/abs/2605.14498">GroupMemBench (Yang et al., 2026)</a> shows why preserving speaker-specific information matters. Our proposed emphasis is a controlled multi-speaker experiment with causal inputs, revisions and complete cost accounting; this is a design direction, not a novelty claim.</p>'
 modules=[('ASR and speaker labels','Audio packets.','Words, provisional speaker labels and their actual release/correction times.'),('Think gate','Newly released speech, old notes and remaining budget.','Skip, update facts, or request a small verification/derivation job.'),('Private work','The selected job and information available so far.','Source-linked facts, task owners, current status and conditional deductions; no spoken reply.'),('Real request arrives','The actual Assistant wake cue and question.','Permission to answer; cancel/revise pending work if needed. The question is hidden from all earlier pre-thinking.'),('Reasoner S2','The actual request, ready notes and allowed history.','A supported answer or clarification, with completion/readiness time.'),('Speech system S1','The actual request and short ready guidance from S2.','Audible response while listening continues. The think gate does not itself authorize speech.')]
 h+='<figure id="thinking-flow"><h4>Proposed data flow</h4><ol class="thinking-flow">'+''.join('<li><strong>'+e(name)+'</strong><p><b>Input:</b> '+e(inp)+'</p><p><b>Output:</b> '+e(out)+'</p></li>' for name,inp,out in modules)+'</ol><figcaption>Figure 1. Proposed separation of private pre-thinking and outward response. Ground-truth answers and selected evidence stay outside this runtime path. This is a design, not a newly executed streaming system.</figcaption></figure>'
 h+='<h4>Experiment A · When should private work start?</h4><p><strong>Hold fixed:</strong> '+e(d['when']['hold_fixed'])+'</p>'+table(3,'Timing policies. Each policy uses the same work task and shared budget caps; actual spent compute can still differ.',['Policy','Rule','What the comparison establishes'],[[e(x['name']),e(x['rule']),e(x['purpose'])] for x in d['when']['policies']])+'<p>'+e(d['when']['budget'])+'</p><p>'+e(d['when']['question_timing'])+'</p><p><strong>Success:</strong> '+e(d['when']['success'])+'</p>'
 h+='<h4>Experiment B · What useful work should pre-thinking do?</h4><p><strong>Hold fixed:</strong> '+e(d['what']['hold_fixed'])+'</p>'+table(4,'Pre-thinking tasks at the same update times. This tests the job performed, rather than changing both its timing and its content at once.',['Task','Work performed','Output to retain'],[[e(x['name']),e(x['work']),e(x['output'])] for x in d['what']['tasks']])+'<p>'+e(d['what']['extra_baseline'])+'</p><p><strong>Success:</strong> '+e(d['what']['success'])+'</p><p><strong>Then combine the axes:</strong> '+e(d['crossed_comparison'])+'</p>'
 h+='<h4>Examples from the actual source meetings</h4>'
 for i,x in enumerate(d['examples']):
  h+='<article class="catalog-question"><h5>'+e(x['title'])+' · '+e(x['meeting'])+'</h5><p class="question">'+e(x['question'])+'</p>'
  for t in x['events']:
   seconds=t['time'];h+='<p><strong>After '+str(int(seconds)//60)+':'+f'{int(seconds)%60:02d}'+' of source audio:</strong> '+e(t['text'])+'</p><p><strong>A safe note would say:</strong> '+e(t['safe_note'])+'</p>'
  if x.get('timing_note'):h+='<p>'+e(x['timing_note'])+'</p>'
  h+='<p>'+e(x['lesson'])+'</p></article>'
 h+='<figure id="thinking-timeline"><h4>Inspect a proposed update</h4><div class="thinking-buttons"><button type="button" data-think-time="proposal">At the single-curved proposal</button><button type="button" data-think-time="revision">After the later double-curved preference</button></div><p id="thinking-example-state" aria-live="polite">19:41 · Single curved is A’s proposed compromise. Keep it tentative.</p><figcaption>Figure 2. Illustration of the state we would want to maintain for the TS3006c source example, not the captured prototype’s actual notes. The two buttons change the example state, not a measured outcome.</figcaption></figure>'
 h+='<h4>Conditions that keep the comparison interpretable</h4><ul>'+''.join('<li><strong>'+e(x['name'])+'.</strong> '+e(x['rule'])+'</li>' for x in d['protocol'])+'</ul><h4>Before submitting any speech inference</h4><ol>'+''.join('<li>'+e(x)+'</li>' for x in d['before_inference'])+'</ol>'
 h+='<h4>Current capacity and the cost of a first replay</h4><ul>'+''.join('<li>'+e(x)+'</li>' for x in d['current_evidence'][1:3]+d['current_evidence'][4:])+'</ul><p><strong>Resource proposal:</strong> '+e(d['resources']['planned'])+'</p><p>'+e(d['resources']['gates'])+'</p><p>'+e(d['resources']['full_prefix_cost_estimate'])+'</p><p><strong>A cheaper first test:</strong> '+e(d['resources']['cheaper_diagnostic'])+'</p><h4>Ready for discussion</h4><ul>'+''.join('<li><strong>'+e(x['question'])+'</strong> '+e(x['recommendation'])+'</li>' for x in d['discussion'])+'</ul><details><summary>Ten checked papers and how they inform this proposal</summary>'
 # Read the checked bibliography independently; no raw user instruction is embedded.
 import json
 from pathlib import Path
 papers=json.loads((Path(__file__).resolve().parents[1]/'research/question-study/literature.json').read_text())['papers']
 h+=table(5,'Primary-source literature supporting the proposed design. Results belong to the cited studies; no numerical result is transferred to AMI. Publication venue is asserted only when checked.',['Paper','Method and reported scope','Implication for this project'],[['<a href="'+x['url']+'">'+e(x['title'])+'</a><p>'+e(x['authors']+', '+str(x['year'])+' · '+x['venue'])+'</p>',e(x['method']+' '+x['results']),e(x['relevance'])] for x in papers])+'</details><p><a href="../research/question-study/design.json">Saved experiment design</a> · <a href="../research/question-study/literature.json">Checked paper metadata</a> · <a href="../research/question-study/capacity-preflight.json">CPU-only context/KV check</a> · <a href="question-checks.html">Completed steps 1–2 and all source evidence</a>.</p></section>'
 return h
JS="""document.querySelectorAll('[data-think-time]').forEach(b=>b.onclick=()=>{document.getElementById('thinking-example-state').textContent=b.dataset.thinkTime==='proposal'?'19:41 · Single curved is A’s proposed compromise. Keep it tentative.':'20:09 · C prefers double curved and A agrees. Preserve that latest preference; do not leave the earlier single-curved proposal as the current choice.';});"""
CSS='''.thinking-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.thinking-flow{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;padding-left:1.5rem}.thinking-flow>li{padding:.8rem;border:1px solid var(--border);border-radius:8px}.thinking-flow p{margin:.5rem 0}.thinking-buttons{display:flex;flex-wrap:wrap;gap:.7rem}.thinking-buttons button{font:inherit;padding:.6rem;white-space:normal;max-width:100%}.thinking-design h4{font-size:1.25rem;margin-top:2rem}.thinking-design h5{font-size:1.1rem}.thinking-design li{margin:1rem 0}.thinking-design th{min-width:10rem}@media(max-width:700px){.thinking-grid,.thinking-flow{grid-template-columns:1fr}}'''
